/// <summary>
///     The <c>AVALogisticsPostalAddressFrm_Extension</c> class is the extension for <c>LogisticsPostalAddress</c>
/// </summary>
[ExtensionOf(formStr(LogisticsPostalAddress))]
final class AVALogisticsPostalAddressFrm_Extension
{
    public  LogisticsPostalAddress              avaLogisticsPostalAddress;
    public  LogisticsLocation                   avaLogisticsLocation;
    public  DirPartyPostalAddressFormHandler    avaPostalAddressForm;
    private boolean                             avaCopyInformation, avaInitOneTime;

}

Method.Source:
/// <summary>
///    AVA <c>init</c> method.
/// </summary>
void init()
{

    next init();

    if(this.args().menuItemName() == menuItemDisplayStr(AVASalesOrderDeliveryAddressNew))
    {
        avaPostalAddressForm = this.args().parmObject();
        this.avaParmCopyInformation(true);
        this.avaInitValues();
    }

    if(this.args().caller().name() == formStr(SalesTable)
        || this.args().caller().name() == formStr(SalesCreateOrder))
    {
        avaPostalAddressForm = this.args().parmObject();
        this.avaParmInitOneTime(true);
        this.avaInitValues();
    }

    this.avaInit();
}

/// <summary>
///    AVA <c>avaInitValues</c> method.
/// </summary>
public void avaInitValues()
{
    SalesTable avaSalesTable    = avaPostalAddressForm.getTransaction();
    avaLogisticsLocation        = LogisticsLocation::find(avaSalesTable.deliveryLocation());
    avaLogisticsPostalAddress   = avaSalesTable.deliveryAddress();
}

/// <summary>
///    AVA <c>updateControls</c> method.
/// </summary>
public void updateControls()
{
    next updateControls();

    if(this.avaParmCopyInformation())
    {
        this.avaInitOneTime(NoYes::No);
    }
    else if(this.avaParmInitOneTime())
    {
        this.avaInitOneTime(NoYes::Yes);
    }

}

/// <summary>
///    AVA <c>avaInitOneTime</c> method.
/// </summary>
/// <param name = "_enableOneTimeControl">NoYes</param>
public void avaInitOneTime(NoYes _enableOneTimeControl)
{
    OneTime.checked(true);
    purposeGroup.enabled(false);
    isPrimary.enabled(false);
    isPrivate.enabled(false);
    actionPane.enabled(false);
    logisticsPostalAddress_ValidFrom.enabled(false);
    logisticsPostalAddress_ValidTo.enabled(false);

    rolesCtrl.set(conNull());
    rolesCtrl.setMandatory(false);

    OneTime.enabled(_enableOneTimeControl);
    avaPostalAddressForm.setIsOneTime(true);

    LogisticsPostalAddress_ds.forceWrite(true);
}

/// <summary>
/// AVA <c>avaParmCopyInformation</c> method
/// </summary>
/// <param name = "_copyInformation">boolean</param>
/// <returns>boolean</returns>
public boolean avaParmCopyInformation(boolean _copyInformation = avaCopyInformation)
{
    avaCopyInformation = _copyInformation;

    return avaCopyInformation;
}

/// <summary>
/// AVA <c>avaParmCopyInformation</c> method
/// </summary>
/// <param name = "_initOneTime">boolean</param>
/// <returns>boolean</returns>
public boolean avaParmInitOneTIme(boolean _initOneTime = avaInitOneTime)
{
    avaInitOneTime = _initOneTime;

    return avaInitOneTime;
}

 /// <summary>
 ///    AVA <c>avaInit</c> method.
 /// </summary>
 public void avaInit()
 {
     FormStringControl   locFormStringControlZIP;

     locFormStringControlZIP = this.LogisticsPostalAddress_ZipCode;

     locFormStringControlZIP.mandatory(true);
}
